An image decoder library processes PNG files from untrusted sources. After decoding a corrupted image, a temporary pixel buffer is freed. Subsequently, the decoder attempts to apply color correction to the output without checking if the buffer is still valid.

void decode_png_and_filter(const unsigned char *data, int len) {
    unsigned char *pixels = malloc(len);
    memcpy(pixels, data, len);
    free(pixels);
    apply_color_filter(pixels, len);
}

A JSON parsing library uses dynamic memory to store parsed key-value pairs. When a malformed JSON document is encountered, the parser deletes the temporary parse tree. However, a reference to a deleted node is later dereferenced during error reporting.

struct JsonNode { char *key; char *value; };
void parse_json(const char *input) {
    JsonNode *root = new JsonNode();
    if (!validate_structure(input)) {
        delete root;
        int len = strlen(root->key);
    }
}

A network packet parser dynamically allocates memory for TCP payload processing. When the payload parser finishes, it frees the buffer and returns to the caller. The caller mistakenly accesses the freed payload buffer when logging the parsed fields.

void process_tcp_segment(struct TcpPacket *pkt) {
    unsigned char *payload = malloc(pkt->len);
    memcpy(payload, pkt->data, pkt->len);
    free(payload);
    log_packet_source(payload, pkt->srcaddr);
}

A font rendering engine caches glyph data in dynamically allocated buffers. When the cache is evicted for memory pressure, the engine deletes old glyph structures. A stale pointer to a deleted glyph is subsequently used when rendering text.

struct GlyphCache { uint8_t *bitmap; int size; };
void render_text(const wchar_t *str) {
    GlyphCache *glyph = new GlyphCache();
    cache_evict(glyph);
    delete glyph;
    draw_glyph_bitmap(glyph->bitmap);
}

An audio decoding codec allocates temporary buffers to hold decoded samples during transcoding. After the transcoding operation completes, the buffers are freed. A subsequent operation on the audio stream tries to access the freed sample buffer.

void transcode_audio(const char *input_file) {
    float *samples = malloc(44100 * sizeof(float));
    decode_samples(input_file, samples);
    free(samples);
    normalize_audio(samples);
}

A database connection pool maintains a list of active connections allocated on the heap. When a connection times out, it is deleted from the pool. A background thread continues to use a cached pointer to the deleted connection object.

struct DbConnection { int fd; char *host; };
void cleanup_stale_connections() {
    DbConnection *conn = pool.get_connection();
    pool.remove_connection(conn);
    delete conn;
    send_keepalive(conn->fd);
}

A configuration file parser reads settings into dynamically allocated strings. After parsing is complete and settings are applied, the temporary strings are freed. An error handler tries to log the configuration details from the freed memory.

void parse_config(const char *file) {
    char *config = malloc(4096);
    read_file(file, config, 4096);
    free(config);
    log_config_error(config);
}

A cryptography library creates temporary key objects during encryption operations. Once encryption is complete, the key object is deleted to clear sensitive data. However, a callback function still holds a reference to the deleted key.

class EncryptionKey { uint8_t data[32]; };
void encrypt_message(const char *msg) {
    EncryptionKey *key = new EncryptionKey();
    delete key;
    register_callback(key);
}

A caching layer allocates memory for frequently accessed objects. When cache entries are evicted due to size limits, the old entries are freed. A subsequent cache lookup fails to check if an entry was freed and tries to return it to the caller.

void evict_cache_entry(CacheEntry *entry) {
    unsigned char *data = entry->data;
    free(data);
    entry = NULL;
    return_cache_value(entry);
}

A protocol buffer decoder allocates structures to hold nested message data. When decoding terminates early due to a parse error, allocated structures are deleted. The error recovery code tries to access fields from the deleted structures.

struct ProtobufMessage { char *data; int len; };
void decode_protobuf(const uint8_t *buf) {
    ProtobufMessage *msg = new ProtobufMessage();
    if (!parse_header(buf)) delete msg;
    access_field(msg->data);
}

An XML parser dynamically allocates nodes for the document tree. When a parsing error occurs, the partial tree is freed to prevent memory leaks. However, the parser retains a pointer to the root node and continues traversing it.

void parse_xml_document(const char *xml) {
    XmlNode *root = malloc(sizeof(XmlNode));
    if (!validate_xml(xml)) {
        free(root);
    }
    traverse_tree(root);
}

A text encoding converter allocates temporary buffers to hold converted characters. After encoding is complete, the buffer is deleted. A string validation function incorrectly tries to validate the freed buffer contents.

void encode_utf8(const wchar_t *input) {
    char *encoded = new char[1024];
    convert_to_utf8(input, encoded);
    delete[] encoded;
    validate_encoding(encoded);
}

A graphics renderer allocates vertex buffers for mesh data. When a rendering context is destroyed, the buffers are freed. A cleanup thread accidentally dereferenced a cached pointer to the freed vertex buffer.

void destroy_graphics_context() {
    float *vertices = malloc(65536);
    glBindBuffer(GL_ARRAY_BUFFER, vbo);
    free(vertices);
    upload_vertex_data(vertices);
}

An HTTP server allocates request objects to handle incoming connections. When a request times out or closes, the request object is deleted. A lingering callback still references the deleted request structure.

struct HttpRequest { char *path; int fd; };
void close_request(HttpRequest *req) {
    HttpRequest *tmp = req;
    delete req;
    send_response(tmp->fd, 200);
}

A data compression library allocates working memory during compression operations. Once compression finishes, the working buffer is freed. A finalization step incorrectly tries to read statistics from the freed working buffer.

void compress_data(const unsigned char *input, int size) {
    unsigned char *work = malloc(size * 2);
    deflate(input, work, size);
    free(work);
    report_stats(work);
}

A utility function concatenates multiple strings into a single buffer for display. The buffer size is calculated based on the first string only, without accounting for subsequent strings. When multiple long strings are concatenated, the function writes past the allocated heap buffer.

void concat_strings(const char *s1, const char *s2) {
    char *result = malloc(strlen(s1) + 1);
    strcpy(result, s1);
    strcat(result, s2);
    free(result);
}

A dynamic array class allocates storage based on an initial size parameter. When elements are added beyond the declared capacity, the class directly writes to heap memory without bounds checking. This causes a heap overflow when the array size calculation is off by one.

class DynArray {
public:
    void push(int val) {
        if (count >= capacity) return;
        data[count++] = val;
    }
private:
    int *data = new int[10];
    int count = 0, capacity = 9;
};

A buffer copy function takes a source buffer and a length parameter from an untrusted caller. The destination buffer is allocated with a fixed size, but the length parameter is not validated. If the source is larger than the destination, memcpy writes past the heap allocation.

void copy_buffer(const unsigned char *src, int len) {
    unsigned char *dst = malloc(256);
    memcpy(dst, src, len);
    process_buffer(dst);
    free(dst);
}

A protocol parser reads a length field from incoming data and allocates a buffer of that size. The parser then copies the data without verifying the declared length matches the actual available data. An attacker can declare a large length and overflow the buffer.

void parse_protocol_message(const uint8_t *data) {
    uint32_t len = *(uint32_t *)data;
    uint8_t *buf = new uint8_t[256];
    memcpy(buf, data + 4, len);
    process_message(buf);
    delete[] buf;
}

A serialization routine packs struct fields into a heap buffer. The buffer size is calculated assuming fixed-size fields, but variable-length fields are not accounted for. When serializing structs with long strings, the write overflows the heap buffer.

void serialize_struct(struct Record *rec) {
    char *buf = malloc(128);
    sprintf(buf, "%s:%d:%s", rec->name, rec->id, rec->data);
    send_over_network(buf);
    free(buf);
}

A user input processor allocates a buffer for command processing with a conservative initial size. User commands are read and appended to the buffer without validation. An attacker submits a command longer than the allocated size, causing a heap overflow.

void process_user_command(const char *cmd) {
    char *buffer = new char[64];
    strcpy(buffer, "CMD: ");
    strcat(buffer, cmd);
    execute_command(buffer);
    delete[] buffer;
}

A file handler allocates a fixed-size buffer to store file or user names from inputs. The name is copied into this buffer using strcpy without bounds checking. If the input name exceeds the allocated size, the heap buffer overflows.

void store_filename(const char *name) {
    char *filename = malloc(32);
    strcpy(filename, name);
    open_file(filename);
    free(filename);
}

A vector-like container dynamically allocates memory for elements. When expanding to accommodate new elements, the size calculation uses integer arithmetic that can overflow. An attacker triggers the overflow by adding many elements.

class Vector {
public:
    void push_back(int val) {
        if (size >= capacity) {
            capacity = (capacity + 1) * 2;
            int *newdata = new int[capacity];
            memcpy(newdata, data, size * 4);
            delete[] data;
            data = newdata;
        }
        data[size++] = val;
    }
private:
    int *data, capacity, size;
};

A tool processes command-line arguments by concatenating them into a single heap-allocated buffer. The buffer size is set to a fixed value without considering the actual total length of all arguments. Long argument lists overflow the heap buffer.

void process_arguments(int argc, char *argv[]) {
    char *cmdline = malloc(128);
    for (int i = 1; i < argc; i++) {
        strcat(cmdline, argv[i]);
        strcat(cmdline, " ");
    }
}

A path processing utility allocates memory to construct full file paths by joining directory and file components. The allocation size is based only on the directory length. When the filename is long, the concatenation operation writes past the allocated buffer.

void construct_path(const char *dir, const char *file) {
    char *path = new char[strlen(dir) + 1];
    sprintf(path, "%s/%s", dir, file);
    open_resource(path);
    delete[] path;
}

A hash table allocates fixed-size buckets to store key-value pairs. When a bucket is full and a new entry is inserted, the code does not check bounds and writes the new entry into the next bucket's memory. This causes a heap overflow into adjacent allocations.

struct Entry { char key[32]; char val[64]; };
void insert_hash_entry(HashTable *ht, const char *k, const char *v) {
    Entry *bucket = ht->buckets[hash(k)];
    bucket->len++;
    strcpy(bucket[bucket->len].key, k);
    strcpy(bucket[bucket->len].val, v);
}

A lexer extracts tokens from source code by copying them into fixed-size heap-allocated buffers. The token buffer size is set conservatively, but long identifiers or strings are not truncated. Oversized tokens overflow the heap buffer.

void extract_token(const char *source, int *pos) {
    char *token = new char[32];
    int i = 0;
    while (source[*pos] && !is_delimiter(source[*pos])) {
        token[i++] = source[(*pos)++];
    }
    token[i] = 0;
}

A metadata parser allocates a fixed buffer for key-value pairs extracted from file headers. The parser reads metadata without validating that the total size does not exceed the buffer. Crafted files with excessive metadata cause heap overflow.

void parse_metadata(FILE *fp) {
    char *meta = malloc(256);
    char line[512];
    while (fgets(line, sizeof(line), fp)) {
        strcat(meta, line);
    }
    process_metadata(meta);
}

A message queue stores incoming messages in a dynamically allocated buffer. The queue size is calculated based on the expected message count, but the actual message size may vary. If messages are larger than anticipated, the queue overflows.

struct Queue {
    void enqueue(const char *msg) {
        if (writePos + strlen(msg) <= capacity) {
            strcpy(buffer + writePos, msg);
            writePos += strlen(msg);
        }
    }
    char *buffer = new char[512];
    int capacity = 512, writePos = 0;
};

A database record handler allocates a buffer to hold serialized record data. The buffer size is based on a schema assumption that does not account for maximum field lengths. When records with longer field values are processed, the buffer overflows during serialization.

void serialize_record(struct DbRecord *rec) {
    char *buf = malloc(256);
    sprintf(buf, "%d|%s|%s|%s", rec->id, rec->name, rec->email, rec->notes);
    write_to_log(buf);
    free(buf);
}
